DROP TABLE IF EXISTS `sueldos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sueldos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `empleado_id` bigint(20) unsigned NOT NULL,
  `periodo` varchar(7) NOT NULL COMMENT 'YYYY-MM',
  `fecha_cierre` date NOT NULL COMMENT 'último día del mes del periodo',
  `moneda_sueldo` enum('USD','BS') NOT NULL COMMENT 'moneda en la que se definió el sueldo',
  `monto_usd` decimal(14,2) DEFAULT NULL COMMENT 'equivalente en USD',
  `monto_bs` decimal(14,2) DEFAULT NULL COMMENT 'equivalente en Bs',
  `tasa_bcv` decimal(14,6) DEFAULT NULL,
  `origen` varchar(20) NOT NULL DEFAULT 'ficha' COMMENT 'ficha | cambio',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `sueldos_empleado_id_periodo_unique` (`empleado_id`,`periodo`),
  KEY `sueldos_empleado_id_periodo_index` (`empleado_id`,`periodo`),
  CONSTRAINT `sueldos_empleado_id_foreign` FOREIGN KEY (`empleado_id`) REFERENCES `empleados` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6887 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
