--
-- Table structure for table `vacaciones`
--

DROP TABLE IF EXISTS `vacaciones`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `vacaciones` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `patrono_id` bigint(20) unsigned NOT NULL,
  `empleado_id` bigint(20) unsigned NOT NULL,
  `fecha_calculo` date NOT NULL,
  `fecha_inicio` date NOT NULL COMMENT 'suministrada por el usuario',
  `fecha_inicio_real` date DEFAULT NULL,
  `fecha_fin_real` date DEFAULT NULL,
  `fecha_reintegro` date DEFAULT NULL,
  `nro_vacacion` tinyint(3) unsigned NOT NULL COMMENT 'años de servicio del periodo',
  `periodo_desde` date NOT NULL COMMENT 'aniversario (N-1) → fecha de ingreso si N=1',
  `periodo_hasta` date NOT NULL COMMENT 'aniversario N',
  `dias_vacaciones` tinyint(3) unsigned NOT NULL DEFAULT 15,
  `dias_adicionales` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `dias_bono` tinyint(3) unsigned NOT NULL DEFAULT 15,
  `dias_bono_adicionales` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `dias_descanso` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `dias_feriados` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `feriados_descanso_en_periodo` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`feriados_descanso_en_periodo`)),
  `salario_normal` decimal(14,2) NOT NULL DEFAULT 0.00,
  `moneda` varchar(3) NOT NULL,
  `estatus_calculo` enum('por_aprobar','aprobada','no_aprobada') NOT NULL DEFAULT 'por_aprobar',
  `estatus_vacacion` enum('pendiente','pagada','disfrutada') NOT NULL DEFAULT 'pendiente',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `vacaciones_periodo_unico` (`patrono_id`,`empleado_id`,`periodo_desde`,`periodo_hasta`),
  KEY `vacaciones_empleado_id_foreign` (`empleado_id`),
  KEY `vacaciones_estatus_idx` (`estatus_calculo`,`estatus_vacacion`),
  CONSTRAINT `vacaciones_empleado_id_foreign` FOREIGN KEY (`empleado_id`) REFERENCES `empleados` (`id`) ON DELETE CASCADE,
  CONSTRAINT `vacaciones_patrono_id_foreign` FOREIGN KEY (`patrono_id`) REFERENCES `patronos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=68 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

