--
-- Table structure for table `vacaciones_recibos`
--

DROP TABLE IF EXISTS `vacaciones_recibos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `vacaciones_recibos` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `vacacion_id` bigint(20) unsigned NOT NULL,
  `empleado_id` bigint(20) unsigned NOT NULL,
  `fecha_emision` date NOT NULL,
  `fecha_inicio` date NOT NULL,
  `fecha_retiro` date NOT NULL,
  `asignaciones` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`asignaciones`)),
  `deducciones` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`deducciones`)),
  `total_asignaciones` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total_deducciones` decimal(14,2) NOT NULL DEFAULT 0.00,
  `neto` decimal(14,2) NOT NULL DEFAULT 0.00,
  `moneda` varchar(3) NOT NULL DEFAULT 'BS',
  `tipo_cambio` decimal(10,4) NOT NULL DEFAULT 0.0000,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `vacaciones_recibos_vacacion_id_foreign` (`vacacion_id`),
  KEY `vacaciones_recibos_empleado_id_foreign` (`empleado_id`),
  CONSTRAINT `vacaciones_recibos_empleado_id_foreign` FOREIGN KEY (`empleado_id`) REFERENCES `empleados` (`id`) ON DELETE CASCADE,
  CONSTRAINT `vacaciones_recibos_vacacion_id_foreign` FOREIGN KEY (`vacacion_id`) REFERENCES `vacaciones` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=44 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
